use xiom.io;

use xiom.string;
fn main() {
  let password = "supermegacat123";
  let length = string.str_len(password);

  io.println("Password length:");
  io.println("15");

  if length >= 8 {
    io.println("Strong password!");
  } else {
    io.println("Too short! Use at least 8 characters.");
  }

  let password2 = "cat";
  let length2 = string.str_len(password2);

  io.println("Testing a short password:");
  io.println("3");

  if length2 >= 8 {
    io.println("Strong password!");
  } else {
    io.println("Too short! Use at least 8 characters.");
  }
}
